class TaskBinding{static Object truck(int p,int f,int m,int c){return new alternate.Truck(p,f,m,c);}static int cargo(Object x){return ((alternate.Truck)x).getCargo();}static void cargo(Object x,int c){((alternate.Truck)x).putCargo(c);}static int[]state(Object x){alternate.Vehicle v=(alternate.Vehicle)x;return new int[]{v.getPassengers(),v.getFuelcap(),v.getMpg()};}static int range(Object x){return ((alternate.Vehicle)x).range();}static double fuel(Object x,int miles){return ((alternate.Vehicle)x).fuelNeeded(miles);}static void setFuel(Object x,int f){((alternate.Vehicle)x).setFuelcap(f);}}
